// Turns icons.json (written by build_icons.py) into lib/icons.js.
//   node tools/extract/gen_icons_js.cjs <tools/slides dir>   (run in the dir holding icons.json)
const fs = require('fs');
const path = require('path');

const icons = JSON.parse(fs.readFileSync(path.resolve('icons.json'), 'utf8'));
const header = `/* eslint-disable */
// GENERATED by tools/extract/build_icons.py + gen_icons_js.cjs from "AEM Live Backgrounds Megadeck.pdf".
// Pure vector path data extracted from the original deck. Do not hand-edit; add your own icons to lib/icons-custom.js.
//
// kind:
//   "tile-glyph"  path in the 0..100 space of an <aem-tile>; cut out of the tile (evenodd)
//   "mono"        single-colour icon, rendered with fill="currentColor"
//   "art"         multi-colour illustration, colours baked in
// src: page number in the original deck the shape was taken from.
export const ICONS = {
`;
const body = Object.entries(icons)
  .map(([k, v]) => `  ${JSON.stringify(k)}: ${JSON.stringify(v)},\n`)
  .join('');
fs.writeFileSync(path.join(process.argv[2], 'lib', 'icons.js'), `${header}${body}};\n`);
